"use client";

import { flexRender, type Table as TableType } from "@tanstack/react-table";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { DataTablePagination } from "./data-table-pagination";
import { DataTableViewOptions } from "./data-table-column-toggle";
import type { PaginatedResult } from "@/hooks/use-criteria-query";
import type { FilterIntegrationProps } from "../data-view-criteria/data-view-filter/data-view-filter";
import { DataViewToolbar, type FileFormat } from "../data-view-criteria/data-view-toolbar";

interface DataTableCriteriaProps<TData> {
  table: TableType<TData>;
  isLoading?: boolean;
  emptyMessage?: string;
  onExport?: (format: FileFormat) => Promise<string> | string;
  data?: PaginatedResult<TData>;
  showColumnToggle?: boolean;
  searchValue?: string;
  onSearchChange?: (value: string) => void;
  searchPlaceholder?: string;
  showSearch?: boolean;
  actionBar?: React.ReactNode;
  filterProps?: FilterIntegrationProps;
}

export function DataTableCriteria<TData>({
  table,
  isLoading = false,
  emptyMessage = "No results.",
  data,
  showColumnToggle = true,
  onExport,
  searchValue = "",
  onSearchChange,
  searchPlaceholder = "Search...",
  showSearch = false,
  actionBar,
  filterProps,
}: DataTableCriteriaProps<TData>) {
  const columnCount = table.getAllColumns().length;

  return (
    <div className="space-y-4">
      <DataViewToolbar
        searchProps={{
          searchValue,
          onSearchChange: onSearchChange ?? (() => {}),
          showSearch,
        }}
        searchPlaceholder={searchPlaceholder}
        filterProps={filterProps}
        actionBar={actionBar}
        onExport={onExport}
      >
        {showColumnToggle && <DataTableViewOptions table={table} />}
      </DataViewToolbar>

      <div className="overflow-hidden rounded-md border">
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => {
                  return (
                    <TableHead key={header.id}>
                      {header.isPlaceholder
                        ? null
                        : flexRender(
                            header.column.columnDef.header,
                            header.getContext()
                          )}
                    </TableHead>
                  );
                })}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {isLoading ? (
              <TableRow>
                <TableCell colSpan={columnCount} className="h-24 text-center">
                  <div className="flex items-center justify-center">
                    <div className="h-6 w-6 animate-spin rounded-full border-2 border-primary border-t-transparent" />
                    <span className="ml-2">Loading...</span>
                  </div>
                </TableCell>
              </TableRow>
            ) : table.getRowModel().rows?.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow
                  key={row.id}
                  data-state={row.getIsSelected() && "selected"}
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id}>
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext()
                      )}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell colSpan={columnCount} className="h-24 text-center">
                  {emptyMessage}
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
      {data && <DataTablePagination table={table} meta={data.meta} />}
    </div>
  );
}

import { type Table } from "@tanstack/react-table";
import {
  ChevronLeft,
  ChevronRight,
  ChevronsLeft,
  ChevronsRight,
} from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import type { PaginatedResult } from "@woltz/rich-domain";

interface DataTablePaginationProps<TData> {
  table: Table<TData>;
  meta?: PaginatedResult<TData>["meta"];
}

export function DataTablePagination<TData>({
  table,
  meta,
}: DataTablePaginationProps<TData>) {
  const selectedCount = table.getFilteredSelectedRowModel().rows.length;
  const totalCount = meta?.total ?? table.getFilteredRowModel().rows.length;
  const currentPage = meta?.page ?? table.getState().pagination.pageIndex + 1;
  const totalPages = meta?.totalPages ?? table.getPageCount();
  const hasNext = meta?.hasNext ?? table.getCanNextPage();
  const hasPrevious = meta?.hasPrevious ?? table.getCanPreviousPage();

  return (
    <div className="flex items-center justify-between px-2">
      <div className="text-muted-foreground flex-1 text-sm">
        {selectedCount > 0 ? (
          <>
            {selectedCount} of {totalCount} row(s) selected.
          </>
        ) : (
          <>
            Showing {table.getRowModel().rows.length} of {totalCount} row(s).
          </>
        )}
      </div>
      <div className="flex items-center space-x-6 lg:space-x-8">
        <div className="flex items-center space-x-2">
          <p className="text-sm font-medium">Rows per page</p>
          <Select
            value={`${table.getState().pagination.pageSize}`}
            onValueChange={(value) => {
              table.setPageSize(Number(value));
            }}
          >
            <SelectTrigger className="h-8 w-[70px]">
              <SelectValue placeholder={table.getState().pagination.pageSize} />
            </SelectTrigger>
            <SelectContent side="top">
              {[10, 20, 25, 30, 40, 50].map((pageSize) => (
                <SelectItem key={pageSize} value={`${pageSize}`}>
                  {pageSize}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
        <div className="flex w-[100px] items-center justify-center text-sm font-medium">
          Page {currentPage} of {totalPages}
        </div>
        <div className="flex items-center space-x-2">
          <Button
            variant="outline"
            size="icon"
            className="hidden size-8 lg:flex"
            onClick={() => table.setPageIndex(0)}
            disabled={!hasPrevious}
          >
            <span className="sr-only">Go to first page</span>
            <ChevronsLeft />
          </Button>
          <Button
            variant="outline"
            size="icon"
            className="size-8"
            onClick={() => table.previousPage()}
            disabled={!hasPrevious}
          >
            <span className="sr-only">Go to previous page</span>
            <ChevronLeft />
          </Button>
          <Button
            variant="outline"
            size="icon"
            className="size-8"
            onClick={() => table.nextPage()}
            disabled={!hasNext}
          >
            <span className="sr-only">Go to next page</span>
            <ChevronRight />
          </Button>
          <Button
            variant="outline"
            size="icon"
            className="hidden size-8 lg:flex"
            onClick={() => table.setPageIndex(totalPages - 1)}
            disabled={!hasNext}
          >
            <span className="sr-only">Go to last page</span>
            <ChevronsRight />
          </Button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { type Table } from "@tanstack/react-table";
import { Settings2 } from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

export function DataTableViewOptions<TData>({
  table,
}: {
  table: Table<TData>;
}) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          variant="outline"
          size="sm"
          className="ml-auto hidden h-8 lg:flex"
        >
          <Settings2 />
          View
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-[150px]">
        <DropdownMenuLabel>Toggle columns</DropdownMenuLabel>
        <DropdownMenuSeparator />
        {table
          .getAllColumns()
          .filter(
            (column) =>
              typeof column.accessorFn !== "undefined" && column.getCanHide()
          )
          .map((column) => {
            return (
              <DropdownMenuCheckboxItem
                key={column.id}
                className="capitalize"
                checked={column.getIsVisible()}
                onCheckedChange={(value) => column.toggleVisibility(!!value)}
              >
                {column.id}
              </DropdownMenuCheckboxItem>
            );
          })}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

"use client";

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from "../../ui/dropdown-menu";
import { Button } from "../../ui/button";
import { Filter as FilterIcon } from "lucide-react";
import { DataViewFilterPopover } from "./data-view-filter-popover";
import { DataViewFilterRow } from "./data-view-filter-row";
import { Badge } from "@/components/ui/badge";
import type { QueryFilter } from "@/lib/filter-utils";
import type { UseCriteriaReturn } from "@/types/use-criteria.type";

/**
 * Props for Filter component integration
 */
export interface FilterIntegrationProps {
  fields: QueryFilter[];
  filters: UseCriteriaReturn<unknown>["filters"];
  addOrReplaceByIndex: UseCriteriaReturn<unknown>["addOrReplaceByIndex"];
  removeFilter: UseCriteriaReturn<unknown>["removeFilter"];
  clearFilters: UseCriteriaReturn<unknown>["clearFilters"];
}

/**
 * Props for Search integration
 */
export interface SearchIntegrationProps {
  searchValue: string;
  onSearchChange: (value: string) => void;
  searchPlaceholder?: string;
  showSearch: boolean;
}

export function DataViewFilter({ filters, ...props }: FilterIntegrationProps) {
  const filtersCount = filters.length;
  const hasFilters = filtersCount > 0;

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="outline" size="sm" className="h-8 relative">
          <FilterIcon className="h-4 w-4" />
          Filter
          {hasFilters && (
            <Badge className="text-[10px] rounded bg-secondary size-[18px] text-foreground">
              {filtersCount}
            </Badge>
          )}
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent className="w-[450px] p-4" align="start">
        {!hasFilters ? (
          <div className="space-y-0.5 mb-4">
            <p className="font-semibold">No filters applied</p>
            <p className="text-sm text-muted-foreground">
              Add filters to your query
            </p>
          </div>
        ) : (
          <div className="space-y-4 mb-4">
            <p className="font-semibold">Filters</p>
            <DataViewFilterRow filters={filters} {...props} />
          </div>
        )}
        <DataViewFilterPopover filters={filters} {...props} />
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

"use client";

import * as React from "react";
import {
  ListFilter,
  Search,
  Type,
  Hash,
  Calendar,
  ToggleLeft,
  X,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  type FieldPath,
  type Filter,
  type FilterOperator,
  type FilterValueFor,
  type OperatorsForType,
  isValidOperatorForType,
} from "@woltz/rich-domain";
import type { UseCriteriaReturn } from "@/types/use-criteria.type";
import { cn } from "@/lib/utils";
import { FilterBooleanValue } from "@/components/filter/filter-boolean-value";
import { FilterDateValue } from "@/components/filter/filter-date-value";
import { FilterOperatorSelector } from "@/components/filter/filter-operator-selector";
import { FilterValueSelector } from "@/components/filter/filter-value-selector";
import {
  type QueryFilter,
  type FilterType,
  type FilterValue,
  getDefaultOperator,
  operatorIsBetween,
  defineDefaultFilterValue,
  operatorRequiresValue,
} from "@/lib/filter-utils";

interface FilterProps {
  fields: QueryFilter[];
  filters: Filter<string, unknown>[];
  addOrReplaceByIndex: UseCriteriaReturn<unknown>["addOrReplaceByIndex"];
  removeFilter: (index: number) => void;
  clearFilters: () => void;
}

const TYPE_ICONS: Record<FilterType, React.ReactNode> = {
  string: <Type className="h-4 w-4" />,
  number: <Hash className="h-4 w-4" />,
  date: <Calendar className="h-4 w-4" />,
  boolean: <ToggleLeft className="h-4 w-4" />,
};

export function DataViewFilterPopover({
  fields,
  filters,
  addOrReplaceByIndex,
  clearFilters,
}: FilterProps) {
  const [addFilterStep, setAddFilterStep] = React.useState<
    null | "field" | "value"
  >(null);
  const [search, setSearch] = React.useState("");
  const [selectedFieldForAdd, setSelectedFieldForAdd] =
    React.useState<QueryFilter | null>(null);
  const [tempOperator, setTempOperator] =
    React.useState<FilterValue["operator"]>("equals");
  const [tempValue, setTempValue] = React.useState<FilterValue["value"]>(null);

  const usedFields = filters.map((filter) => filter.field);
  const remainingFields = fields.filter(
    (field) => !usedFields.includes(field.field)
  );

  const HAS_FIELDS_REMAINING = remainingFields.length > 0;

  const filteredRemainingFields = remainingFields.filter((field) =>
    field.fieldLabel.toLowerCase().includes(search.toLowerCase())
  );

  const handleSelectFieldForAdd = (field: QueryFilter) => {
    setSelectedFieldForAdd(field);
    const defaultOp = getDefaultOperator(field.type);
    setTempOperator(defaultOp);

    const defaultDateRange = [
      new Date().toISOString(),
      new Date(new Date().setMonth(new Date().getMonth() + 1)).toISOString(),
    ];

    const defaultValue = operatorIsBetween(defaultOp)
      ? field.type === "number"
        ? [0, 0]
        : field.type === "date"
        ? defaultDateRange
        : ["", ""]
      : defineDefaultFilterValue(field.type, defaultOp);

    console.log("defaultValue", defaultValue);
    setTempValue(defaultValue);
    setSearch("");
    setAddFilterStep("value");
  };

  const onSelectOperator = (op: FilterOperator) => {
    if (!selectedFieldForAdd) return;

    const defaultDateRange = [
      new Date().toISOString(),
      new Date(new Date().setMonth(new Date().getMonth() + 1)).toISOString(),
    ];
    const defaultValue =
      selectedFieldForAdd.type === "date"
        ? defaultDateRange
        : selectedFieldForAdd.type === "number"
        ? [0, 0]
        : ["", ""];

    const prevOperatorIsBetween = operatorIsBetween(tempOperator);
    const newOperatorIsBetween = operatorIsBetween(op);

    setTempOperator(op);

    if (!operatorRequiresValue(op)) {
      setTempValue(null);
    } else if (!prevOperatorIsBetween && newOperatorIsBetween) {
      setTempValue(defaultValue);
    } else if (prevOperatorIsBetween && !newOperatorIsBetween) {
      setTempValue(defineDefaultFilterValue(selectedFieldForAdd.type, op));
    }
  };

  const handleConfirmAddFilter = () => {
    if (!selectedFieldForAdd || tempValue === null) return;

    addOrReplaceByIndex({
      field: selectedFieldForAdd.field as FieldPath<unknown>,
      operator: tempOperator as OperatorsForType<never>,
      value: tempValue as FilterValueFor<never>,
    });

    setAddFilterStep(null);
    setSelectedFieldForAdd(null);
    setTempOperator("equals");
    setTempValue(null);
  };

  const handleCancelAddFilter = () => {
    setAddFilterStep(null);
    setSelectedFieldForAdd(null);
    setTempOperator("equals");
    setTempValue(null);
    setSearch("");
  };

  const canAddFilter = React.useMemo(() => {
    if (!selectedFieldForAdd) return false;
    return isValidOperatorForType(tempValue, tempOperator);
  }, [tempValue, tempOperator, selectedFieldForAdd]);

  const STEP_VALUE_ADD_FILTER_BUTTON_DISABLED =
    !canAddFilter || tempValue === null || tempValue === "";

  return (
    <div className="flex items-center gap-2">
      <Popover
        open={addFilterStep !== null}
        onOpenChange={(open) => !open && handleCancelAddFilter()}
      >
        <PopoverTrigger asChild>
          <Button
            variant="outline"
            size="sm"
            className="h-8 gap-1.5 bg-transparent"
            disabled={!HAS_FIELDS_REMAINING}
            onClick={() => setAddFilterStep("field")}
          >
            <ListFilter className="h-4 w-4" />
            Add Filter
          </Button>
        </PopoverTrigger>
        <PopoverContent
          className={cn(
            addFilterStep === "field" ? "p-0" : "min-w-64 p-3",
            "bg-card w-fit"
          )}
          align="start"
        >
          {addFilterStep === "field" ? (
            <>
              <div className="p-2 border-b border-border">
                <div className="relative">
                  <Search className="absolute left-2 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                  <Input
                    placeholder="Search fields..."
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                    className="h-8 pl-8"
                  />
                </div>
              </div>
              <div className="max-h-60 overflow-y-auto p-1">
                {filteredRemainingFields.map((field) => (
                  <button
                    key={field.field}
                    onClick={() => handleSelectFieldForAdd(field)}
                    className="flex w-full items-center gap-2 rounded-sm px-2 py-1.5 text-sm hover:bg-accent"
                  >
                    <span className="text-muted-foreground">
                      {TYPE_ICONS[field.type]}
                    </span>
                    <span className="flex-1 text-left">{field.fieldLabel}</span>
                  </button>
                ))}
                {filteredRemainingFields.length === 0 && (
                  <div className="py-6 text-center text-sm text-muted-foreground">
                    {search
                      ? "No fields found"
                      : "All fields are already in use"}
                  </div>
                )}
              </div>
            </>
          ) : addFilterStep === "value" && selectedFieldForAdd ? (
            <div className="space-y-3">
              <div className="flex items-center gap-2 pb-2 border-b">
                <span className="text-muted-foreground">
                  {TYPE_ICONS[selectedFieldForAdd.type]}
                </span>
                <span className="font-medium text-foreground text-sm">
                  {selectedFieldForAdd.fieldLabel}
                </span>
              </div>

              <div className="flex items-center gap-2 ">
                <div className="space-y-2 h-7">
                  <FilterOperatorSelector
                    type={selectedFieldForAdd.type}
                    isNullable={selectedFieldForAdd.isNullable}
                    selectedOperator={tempOperator}
                    onSelect={onSelectOperator}
                  />
                </div>

                {operatorRequiresValue(tempOperator) && (
                  <div className="space-y-2 flex-1 h-7">
                    {selectedFieldForAdd.type === "date" ? (
                      <FilterDateValue
                        operator={tempOperator}
                        value={tempValue as string | [string, string] | null}
                        onChange={setTempValue}
                      />
                    ) : selectedFieldForAdd.type === "boolean" ? (
                      <FilterBooleanValue
                        value={tempValue as boolean | null}
                        onChange={setTempValue}
                      />
                    ) : (
                      <FilterValueSelector
                        filter={selectedFieldForAdd}
                        operator={tempOperator}
                        value={tempValue as string | string[]}
                        onChange={setTempValue}
                      />
                    )}
                  </div>
                )}
              </div>

              <div className="flex gap-2 pt-2">
                <Button
                  variant="outline"
                  size="sm"
                  className="h-7 flex-1 text-xs"
                  onClick={handleCancelAddFilter}
                >
                  Cancel
                </Button>
                <Button
                  size="sm"
                  className="h-7 flex-1 text-xs"
                  disabled={STEP_VALUE_ADD_FILTER_BUTTON_DISABLED}
                  onClick={handleConfirmAddFilter}
                >
                  Add Filter
                </Button>
              </div>
            </div>
          ) : null}
        </PopoverContent>
      </Popover>
      <Button
        variant="outline"
        size="sm"
        className="h-8 gap-1.5"
        onClick={clearFilters}
      >
        <X className="h-4 w-4" />
        Clear Filters
      </Button>
    </div>
  );
}

"use client";

import { FilterRow } from "@/components/filter/filter-row";
import {
  type QueryFilter,
  type FilterValue,
  getDefaultOperator,
  defineDefaultFilterValue,
  operatorSupportsMultipleValues,
  operatorIsBetween,
} from "@/lib/filter-utils";
import {
  type FieldPath,
  type Filter,
  type FilterValueFor,
  type OperatorsForType,
} from "@woltz/rich-domain";
import type { UseCriteriaReturn } from "@/types/use-criteria.type";
import { useDebounceCallback } from "@/hooks/use-debounce-callback";

interface FilterProps {
  fields: QueryFilter[];
  filters: Filter<string, unknown>[];
  addOrReplaceByIndex: UseCriteriaReturn<unknown>["addOrReplaceByIndex"];
  removeFilter: (index: number) => void;
  clearFilters: () => void;
}

export function DataViewFilterRow({
  fields,
  filters,
  addOrReplaceByIndex,
  removeFilter,
}: FilterProps) {
  const filterValues: FilterValue[] = filters.map((filter) => ({
    field: filter.field,
    operator: filter.operator as FilterValue["operator"],
    value: filter.value as FilterValue["value"],
  }));

  const usedFields = filters.map((filter) => filter.field);

  const handleUpdateFilter = (index: number, newValue: FilterValue) => {
    const prevFilter = filterValues[index];
    if (!prevFilter) return;

    const newField = fields.find((f) => f.field === newValue.field);
    const prevField = fields.find((f) => f.field === prevFilter.field);
    if (!newField || !prevField) return;

    const fieldTypeChanged = prevField.type !== newField.type;

    const operator = fieldTypeChanged
      ? getDefaultOperator(newField.type)
      : newValue.operator;

    let value =
      newValue.value === null || fieldTypeChanged
        ? defineDefaultFilterValue(newField.type, newValue.operator)
        : newValue.value;

    const newOperatorIsArrayOperator = operatorSupportsMultipleValues(operator);
    const prevOperatorIsArrayOperator = operatorSupportsMultipleValues(
      prevFilter.operator
    );
    const newOperatorIsBetween = operatorIsBetween(operator);
    const prevOperatorIsBetween = operatorIsBetween(prevFilter.operator);

    if (prevOperatorIsArrayOperator && !newOperatorIsArrayOperator) {
      value = null;
    }

    if (prevOperatorIsBetween && !newOperatorIsBetween) {
      value = null;
    } else if (!prevOperatorIsBetween && newOperatorIsBetween) {
      value = newField.type === "number" ? [0, 0] : ["", ""];
    }

    addOrReplaceByIndex({
      field: newField.field as FieldPath<unknown>,
      operator: operator as OperatorsForType<never>,
      value: value as FilterValueFor<never>,
      replaceIndex: index,
    });
  };

  const [handleUpdateFilterDebounced] = useDebounceCallback(
    (index: number, newValue: FilterValue) => {
      handleUpdateFilter(index, newValue);
    },
    300
  );

  const handleSelectField = (index: number, newValue: FilterValue) => {
    const filterToUpdate = filters[index];
    if (!filterToUpdate) return;

    const newField = fields.find((f) => f.field === newValue.field);
    const oldField = fields.find((f) => f.field === filterToUpdate.field);

    if (!newField || !oldField) return;

    let value = filterToUpdate.value;
    let operator = newValue.operator;

    if (newField.type !== oldField.type) {
      operator = getDefaultOperator(newField.type);
      value = defineDefaultFilterValue(newField.type);
    }

    addOrReplaceByIndex({
      field: newValue.field as FieldPath<unknown>,
      operator: operator as OperatorsForType<never>,
      value: value as FilterValueFor<never>,
      replaceIndex: index,
    });
  };

  const handleRemoveFilter = (index: number) => {
    removeFilter(index);
  };

  return (
    <div className="space-y-2">
      {filterValues.map((filter, index) => (
        <FilterRow
          key={`${filter.field}-${index}`}
          fields={fields}
          value={filter}
          onChange={(newValue) => handleUpdateFilterDebounced(index, newValue)}
          onSelectField={(newValue) => handleSelectField(index, newValue)}
          onRemove={() => handleRemoveFilter(index)}
          usedFields={usedFields}
        />
      ))}
    </div>
  );
}

import type {
  ColumnDef,
  SortingState,
  TableOptions,
  Table,
} from "@tanstack/react-table";
import type { Criteria, PaginatedJsonResult } from "@woltz/rich-domain";
import type { UseCriteriaOptions, UseCriteriaReturn } from "./use-criteria.type";
import type { QueryFilter } from "../lib/filter-utils";
import type { QueryKey, UseQueryResult } from "@tanstack/react-query";
import type { FilterIntegrationProps, SearchIntegrationProps } from "@/components/data-view-criteria/data-view-filter/data-view-filter";

/**
 * Configuration options for useCriteriaTable hook
 */
export interface UseCriteriaTableOptions<T> {
  /**
   * Table column definitions
   */
  columns: ColumnDef<T>[];

  /**
   * Filter field definitions for the Filter component
   */
  filterFields?: QueryFilter[];

  /**
   * Query key for React Query
   */
  queryKey: QueryKey;

  /**
   * Query function that receives criteria and returns paginated result
   */
  queryFn: (criteria: Criteria<T>) => Promise<PaginatedJsonResult<T>>;

  /**
   * Options for useCriteria hook
   */
  criteriaOptions?: UseCriteriaOptions<T>;

  /**
   * Additional options for useReactTable
   */
  tableOptions?: Partial<TableOptions<T>>;

  /**
   * Enable row selection
   */
  enableRowSelection?: boolean;

  /**
   * Enable multi-sort
   */
  enableMultiSort?: boolean;

  /**
   * Debounce delay for search input in milliseconds
   * @default 300
   */
  searchDebounceMs?: number;
}



/**
 * Return type for useCriteriaTable hook
 */
export interface UseCriteriaTableReturn<T> {
  /**
   * TanStack Table instance
   */
  table: Table<T>;

  /**
   * All criteria state and methods
   */
  criteria: UseCriteriaReturn<T>;

  /**
   * React Query result with paginated data
   */
  query: UseQueryResult<PaginatedJsonResult<T>, Error>;

  /**
   * Paginated result data (shortcut for query.data)
   */
  data?: PaginatedJsonResult<T>;

  /**
   * Loading state (shortcut for query.isLoading)
   */
  isLoading: boolean;

  /**
   * Error state (shortcut for query.error)
   */
  error: Error | null;

  /**
   * Props to spread into Filter component
   */
  filterProps: FilterIntegrationProps;

  /**
   * Props to spread into DataTableCriteria for search
   */
  searchProps: SearchIntegrationProps;

  /**
   * Current sorting state
   */
  sorting: SortingState;

  /**
   * Update sorting (syncs with criteria)
   */
  setSorting: (sorting: SortingState) => void;
}

import { useCallback, useMemo, useState } from "react";
import {
  getCoreRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
  type OnChangeFn,
  type PaginationState,
  type SortingState,
  type VisibilityState,
} from "@tanstack/react-table";
import { useQuery } from "@tanstack/react-query";
import { useCriteria } from "./use-criteria";
import { useDebounceCallback } from "./use-debounce-callback";
import type {
  UseCriteriaTableOptions,
  UseCriteriaTableReturn,
} from "../types/use-criteria-table.type";
import type { FieldPath, OrderDirection } from "@woltz/rich-domain";

export function useCriteriaTable<T>(
  options: UseCriteriaTableOptions<T>
): UseCriteriaTableReturn<T> {
  const {
    columns,
    filterFields = [],
    queryKey,
    queryFn,
    criteriaOptions = {},
    tableOptions = {},
    enableRowSelection = false,
    enableMultiSort = false,
    searchDebounceMs = 300,
  } = options;

  const criteriaState = useCriteria<T>(criteriaOptions);

  const [debouncedSetSearch] = useDebounceCallback((value: string) => {
    criteriaState.setSearch(value);
  }, searchDebounceMs);

  const handleSearchChange = useCallback(
    (value: string) => {
      debouncedSetSearch(value);
    },
    [debouncedSetSearch]
  );

  const query = useQuery({
    queryKey: [...queryKey, criteriaState.criteria.toJSON()],
    queryFn: async () => await queryFn(criteriaState.criteria),
  });

  const [columnVisibility, setColumnVisibility] = useState<VisibilityState>({});

  const sorting: SortingState = useMemo(() => {
    return criteriaState.sorting.map((order) => ({
      id: order.field,
      desc: order.direction === "desc",
    }));
  }, [criteriaState.sorting]);

  const handleSortingChange: OnChangeFn<SortingState> = useCallback(
    (updater) => {
      const newSorting =
        typeof updater === "function" ? updater(sorting) : updater;

      if (newSorting.length === 0) {
        criteriaState.clearSort();
        return;
      }

      const sortItem = newSorting[0];
      if (!sortItem) return;

      const direction: OrderDirection = sortItem.desc ? "desc" : "asc";
      criteriaState.addSort(sortItem.id as FieldPath<T>, direction);
    },
    [sorting, criteriaState]
  );

  const paginationState: PaginationState = useMemo(() => {
    return {
      pageIndex: criteriaState.pagination.page - 1, // TanStack uses 0-based index
      pageSize: criteriaState.pagination.limit,
    };
  }, [criteriaState.pagination]);

  const handlePaginationChange: OnChangeFn<PaginationState> = useCallback(
    (updater) => {
      const newPagination =
        typeof updater === "function" ? updater(paginationState) : updater;

      if (newPagination.pageIndex !== paginationState.pageIndex) {
        criteriaState.setPage(newPagination.pageIndex + 1); // Convert back to 1-based
      }

      if (newPagination.pageSize !== paginationState.pageSize) {
        criteriaState.setPageSize(newPagination.pageSize);
      }
    },
    [paginationState, criteriaState]
  );

  const pageCount = useMemo(() => {
    return query.data?.meta.totalPages ?? -1;
  }, [query.data?.meta.totalPages]);

  // eslint-disable-next-line react-hooks/incompatible-library
  const table = useReactTable({
    data: (query.data?.data as T[]) ?? [],
    columns,
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getPaginationRowModel: getPaginationRowModel(),

    // Manual pagination and sorting (controlled by criteria)
    manualPagination: true,
    manualSorting: true,

    // State
    state: {
      sorting,
      pagination: paginationState,
      columnVisibility,
    },

    // Handlers
    onSortingChange: handleSortingChange,
    onPaginationChange: handlePaginationChange,
    onColumnVisibilityChange: setColumnVisibility,

    // Config
    enableRowSelection,
    enableMultiSort,
    pageCount,

    // Merge additional table options
    ...tableOptions,
  });

  const filterProps = useMemo(
    () => ({
      fields: filterFields,
      filters: criteriaState.filters,
      addOrReplaceByIndex: criteriaState.addOrReplaceByIndex,
      removeFilter: criteriaState.removeFilter,
      clearFilters: criteriaState.clearFilters,
    }),
    [
      filterFields,
      criteriaState.filters,
      criteriaState.addOrReplaceByIndex,
      criteriaState.removeFilter,
      criteriaState.clearFilters,
    ]
  );

  const searchProps = useMemo(
    () => ({
      searchValue: criteriaState.search || "",
      onSearchChange: handleSearchChange,
      showSearch: true,
    }),
    [criteriaState.search, handleSearchChange]
  );

  return {
    table,
    criteria: criteriaState,
    query,
    data: query.data,
    isLoading: query.isLoading,
    error: query.error,
    filterProps,
    searchProps,
    sorting,
    setSorting: handleSortingChange,
  };
}
